  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, BOX_W, ROW_H, GAP = 20, kit.W - 40, 56, 10
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['engine'] = function()
-- The reader's draughts player: alpha-beta with iterative deepening; at the end of the depth it
-- goes on while a capture is on the board (captures are compulsory, so a quiet score in the middle
-- of an exchange would be wrong); the best move of the last depth first, then the longest
-- captures, then killer moves. The evaluation: men and kings, men further up the board, the back
-- row kept, the middle of the board, and a little noise per level so games differ.
--
-- think(pos, level, opts) runs in a coroutine as Chess does: every 100 nodes it asks
-- opts.clock() and yields once the slice (opts.slice_ms) is used up; past opts.limit_ms it plays
-- the best move of the last depth it finished. Outside a coroutine (tests) it never yields.

local R = require('rules')
local E = {}

local WIN = 100000
local INF = 1000000

E.LEVELS = {
  { name = 'Beginner', depth = 2, ms = 500, noise = 120 },
  { name = 'Easy', depth = 4, ms = 1500, noise = 40 },
  { name = 'Medium', depth = 8, ms = 3500, noise = 10 },
  { name = 'Hard', depth = 14, ms = 8000, noise = 3 },
}

local MAN, KING = 100, { [R.CHECKERS] = 300, [R.DAMA] = 350 }

-- the score for the side to move
local function evaluate(pos)
  local b, v = pos.b, pos.variant
  local king = KING[v]
  local s = 0
  for i = 1, 64 do
    local p = b[i]
    if p ~= 0 then
      local r, c = (i - 1) // 8, (i - 1) % 8
      local mid = (c >= 2 and c <= 5) and 4 or 0
      if p == 1 then s = s + MAN + r * 6 + mid + ((r == 0 and v == R.CHECKERS) and 8 or 0)
      elseif p == -1 then s = s - MAN - (7 - r) * 6 - mid - ((r == 7 and v == R.CHECKERS) and 8 or 0)
      elseif p == 2 then s = s + king + mid
      else s = s - king - mid end
    end
  end
  return s * pos.side
end
E.evaluate = evaluate

local Search = {}
Search.__index = Search

function Search:tick()
  self.nodes = self.nodes + 1
  if self.nodes % 100 ~= 0 then return end
  local now = self.clock()
  if self.limit and now - self.start >= self.limit then self.stopped = true; return end
  if self.yield and now - self.slice_start >= self.slice then
    coroutine.yield()
    self.slice_start = self.clock()
  end
end

local function kkey(m) return m.from * 64 + m.to end

-- order: the move to try first, longer captures, killers
local function order(list, first, killers)
  local keys = {}
  for i, m in ipairs(list) do
    local k = #m.caps * 1000
    if first and kkey(m) == kkey(first) and #m.caps == #first.caps then k = k + 100000 end
    if killers and (killers[1] == kkey(m) or killers[2] == kkey(m)) then k = k + 500 end
    if m.promo then k = k + 300 end
    keys[i] = k
  end
  -- insertion sort by key, the lists are short
  for i = 2, #list do
    local m, k = list[i], keys[i]
    local j = i - 1
    while j >= 1 and keys[j] < k do list[j + 1], keys[j + 1] = list[j], keys[j]; j = j - 1 end
    list[j + 1], keys[j + 1] = m, k
  end
end

function Search:search(pos, depth, alpha, beta, ply)
  self:tick()
  if self.stopped then return 0 end
  if pos.quiet >= R.QUIET_PLIES then return 0 end
  -- at the end of the depth: a quiet position is scored as it stands; with a capture on the board
  -- the search goes on (captures are compulsory). A side with no move at all is found one ply on.
  if depth <= 0 and not R.has_capture(pos) then return evaluate(pos) end
  local list = R.moves(pos)
  if #list == 0 then return -(WIN - ply) end
  if ply > 60 then return evaluate(pos) end
  local killers = self.killers[ply]
  order(list, nil, killers)
  local best = -INF
  for _, m in ipairs(list) do
    R.make(pos, m)
    local v = -self:search(pos, depth - 1, -beta, -alpha, ply + 1)
    R.unmake(pos, m)
    if self.stopped then return 0 end
    if v > best then best = v end
    if v > alpha then alpha = v end
    if alpha >= beta then
      if #m.caps == 0 then
        killers = killers or {}
        if killers[1] ~= kkey(m) then killers[2] = killers[1]; killers[1] = kkey(m) end
        self.killers[ply] = killers
      end
      break
    end
  end
  return best
end

-- the best move for the side to move, its score, the depth reached and the nodes searched
function E.think(pos, level, opts)
  opts = opts or {}
  local L = E.LEVELS[level] or E.LEVELS[3]
  local s = setmetatable({ clock = opts.clock or function() return 0 end, slice = opts.slice_ms or 200,
                           limit = opts.limit_ms or L.ms, nodes = 0, killers = {}, stopped = false }, Search)
  s.yield = opts.yield ~= false and coroutine.isyieldable()
  s.start = s.clock()
  s.slice_start = s.start
  local random = opts.random or math.random
  local root = R.moves(pos)
  if #root == 0 then return nil end
  if #root == 1 then return root[1], 0, 0, 0 end            -- a forced move: no need to think
  local noise = {}
  for i = 1, #root do noise[root[i]] = math.floor((random() - 0.5) * 2 * L.noise) end
  local best, best_score, reached = root[1], -INF, 0
  for depth = 1, L.depth do
    local alpha = -INF
    local this_best, this_score = nil, -INF
    order(root, best, nil)
    for _, m in ipairs(root) do
      R.make(pos, m)
      local v = -s:search(pos, depth - 1, -INF, -alpha + L.noise, 1)
      R.unmake(pos, m)
      if s.stopped then break end
      local score = v + (math.abs(v) < WIN - 1000 and noise[m] or 0)
      if score > this_score then this_best, this_score = m, score end
      if score > alpha then alpha = score end
    end
    if s.stopped then
      if this_best and this_score > best_score then best, best_score = this_best, this_score end
      break
    end
    best, best_score, reached = this_best, this_score, depth
    if math.abs(this_score) >= WIN - 1000 then break end
  end
  return best, best_score, reached, s.nodes
end

E.WIN = WIN
return E
end

__mods['rules'] = function()
-- The rules of two draughts games, with no screen: English checkers and Turkish draughts (Dama).
--
-- The board is b[1..64], square = row * 8 + col + 1 with row 0 the first side's back row (at the
-- bottom for it) and col 0 its left. Pieces: 1 a man and 2 a king of the side that moves first
-- (side 1), -1 and -2 the other side's (side -1). Side 1 starts on rows 0-2 (checkers) or 1-2
-- (Dama) and moves up the board.
--
-- English checkers: 12 men each on the dark squares; men move one square diagonally forward and
-- capture by jumping an adjacent piece diagonally forward; kings move and jump one square in any
-- diagonal direction. Capturing is compulsory and a capture goes on while the piece can jump
-- again (any such line may be chosen); the pieces taken stay on the board until the move ends and
-- cannot be jumped twice. A man reaching the far row is crowned, and that ends the move.
--
-- Dama: 16 men each on the second and third rows; men move one square forward or sideways and
-- capture the same way; kings move any distance along a row or column and capture a piece any
-- distance away, landing on any empty square beyond it. Pieces taken leave the board at once, so
-- their squares can be crossed later in the same move; a king may not turn back (180 degrees)
-- between two captures. The line that takes the most pieces must be played (men and kings count
-- the same). A man that reaches the far row during a capture finishes it as a man and is crowned
-- when the move ends.
--
-- A move is a table { from, to, caps = { squares }, cv = { pieces taken }, path = { squares
-- landed on }, promo = true when it crowns }; make and unmake change b in place. The side to move
-- with no legal move has lost.

local R = {}

R.CHECKERS, R.DAMA = 'checkers', 'dama'

local function sq(row, col) return row * 8 + col + 1 end
local function row_of(s) return (s - 1) // 8 end
local function col_of(s) return (s - 1) % 8 end
R.sq, R.row, R.col = sq, row_of, col_of

function R.name(s) return string.char(97 + col_of(s), 49 + row_of(s)) end
function R.square(n) return sq(n:byte(2) - 49, n:byte(1) - 97) end

-- a dark square of checkers (a1 is dark, as on a chess board)
function R.dark(s) return (row_of(s) + col_of(s)) % 2 == 0 end

------------------------------------------------------------------ positions

function R.new(variant)
  local b = {}
  for s = 1, 64 do b[s] = 0 end
  for s = 1, 64 do
    local r = row_of(s)
    if variant == R.DAMA then
      if r == 1 or r == 2 then b[s] = 1 elseif r == 5 or r == 6 then b[s] = -1 end
    elseif R.dark(s) then
      if r <= 2 then b[s] = 1 elseif r >= 5 then b[s] = -1 end
    end
  end
  return { b = b, side = 1, variant = variant, quiet = 0 }
end

-- the position as text: the variant, the side to move and the 64 squares (o O x X .)
local CH = { [1] = 'o', [2] = 'O', [-1] = 'x', [-2] = 'X', [0] = '.' }
function R.key(pos)
  local t = {}
  for s = 1, 64 do t[s] = CH[pos.b[s]] end
  return (pos.side > 0 and '1' or '2') .. table.concat(t)
end

function R.from_key(variant, k, quiet)
  local b = {}
  local back = { o = 1, O = 2, x = -1, X = -2 }
  for s = 1, 64 do b[s] = back[k:sub(s + 1, s + 1)] or 0 end
  return { b = b, side = k:sub(1, 1) == '1' and 1 or -1, variant = variant, quiet = quiet or 0 }
end

function R.copy(pos)
  local b = {}
  for s = 1, 64 do b[s] = pos.b[s] end
  return { b = b, side = pos.side, variant = pos.variant, quiet = pos.quiet }
end

------------------------------------------------------------------ moves

local DIAG = { { 1, -1 }, { 1, 1 }, { -1, -1 }, { -1, 1 } }
local ORTHO = { { 1, 0 }, { 0, -1 }, { 0, 1 }, { -1, 0 } }

-- the directions a piece may go, made once: a man only forward (and, in Dama, sideways)
local DIRS = {
  [R.CHECKERS] = { [1] = { DIAG[1], DIAG[2] }, [-1] = { DIAG[3], DIAG[4] }, [2] = DIAG, [-2] = DIAG },
  [R.DAMA] = { [1] = { { 1, 0 }, { 0, -1 }, { 0, 1 } }, [-1] = { { -1, 0 }, { 0, -1 }, { 0, 1 } }, [2] = ORTHO, [-2] = ORTHO },
}
-- the square one step from s in direction d (a table of { dr, dc }), or 0 off the board
local STEP = {}
for _, list in ipairs({ DIAG, ORTHO }) do
  for _, d in ipairs(list) do
    local t = {}
    for s = 1, 64 do
      local r, c = (s - 1) // 8 + d[1], (s - 1) % 8 + d[2]
      t[s] = (r >= 0 and r < 8 and c >= 0 and c < 8) and (r * 8 + c + 1) or 0
    end
    STEP[d] = t
  end
end
for _, v in pairs(DIRS) do
  for _, list in pairs(v) do
    for _, d in ipairs(list) do
      if not STEP[d] then
        for _, o in ipairs({ DIAG, ORTHO }) do
          for _, e in ipairs(o) do if e[1] == d[1] and e[2] == d[2] then STEP[d] = STEP[e] end end
        end
      end
    end
  end
end
local OPP = {}                                       -- the direction straight back
for _, list in ipairs({ DIAG, ORTHO }) do
  for _, d in ipairs(list) do
    for _, e in ipairs(list) do if e[1] == -d[1] and e[2] == -d[2] then OPP[d] = e end end
  end
end
for _, v in pairs(DIRS) do
  for _, list in pairs(v) do
    for _, d in ipairs(list) do
      if not OPP[d] then
        for _, e in ipairs(ORTHO) do if e[1] == -d[1] and e[2] == -d[2] then OPP[d] = e end end
      end
    end
  end
end

local NONE = {}                                      -- the caps and cv of a plain move
local function last_row(side) return side > 0 and 7 or 0 end

local function copy(t) local o = {}; for i = 1, #t do o[i] = t[i] end; return o end

-- English checkers: the jumps from s, the taken pieces staying on the board (marked in taken)
local function checkers_jumps(b, s, p, side, caps, cv, path, taken, out)
  local more = false
  local ds = DIRS[R.CHECKERS][p]
  for i = 1, #ds do
    local step = STEP[ds[i]]
    local over = step[s]
    local to = over ~= 0 and step[over] or 0
    if to ~= 0 and b[over] * side < 0 and not taken[over] and b[to] == 0 then
      more = true
      local n = #caps + 1
      caps[n], cv[n], path[n] = over, b[over], to
      taken[over] = true
      if (p == 1 or p == -1) and (to - 1) // 8 == last_row(side) then
        out[#out + 1] = { caps = copy(caps), cv = copy(cv), path = copy(path), promo = true }   -- crowned: it stops
      else
        checkers_jumps(b, to, p, side, caps, cv, path, taken, out)
      end
      taken[over] = nil
      caps[n], cv[n], path[n] = nil, nil, nil
    end
  end
  if not more and #caps > 0 then out[#out + 1] = { caps = copy(caps), cv = copy(cv), path = copy(path) } end
end

-- Dama: the jumps from s, a taken piece leaving the board at once; last: the direction of the
-- previous jump (a king may not go straight back)
local function dama_jumps(b, s, p, side, caps, cv, path, last, out)
  local king = p == 2 or p == -2
  local more = false
  local ds = DIRS[R.DAMA][p]
  for i = 1, #ds do
    local d = ds[i]
    if not (king and last and OPP[last] == d) then
      local step = STEP[d]
      local over = step[s]
      if king then while over ~= 0 and b[over] == 0 do over = step[over] end end
      if over ~= 0 and b[over] * side < 0 then
        local to = step[over]
        while to ~= 0 and b[to] == 0 do
          more = true
          local victim = b[over]
          b[over] = 0
          local n = #caps + 1
          caps[n], cv[n], path[n] = over, victim, to
          dama_jumps(b, to, p, side, caps, cv, path, d, out)
          caps[n], cv[n], path[n] = nil, nil, nil
          b[over] = victim
          if not king then break end                      -- a man lands just beyond
          to = step[to]
        end
      end
    end
  end
  if not more and #caps > 0 then out[#out + 1] = { caps = copy(caps), cv = copy(cv), path = copy(path) } end
end

-- can the side to move capture? (the end of a search asks this at every position: no tables made)
function R.has_capture(pos)
  local b, side = pos.b, pos.side
  local dirs = DIRS[pos.variant]
  local dama = pos.variant == R.DAMA
  for s = 1, 64 do
    local p = b[s]
    if p * side > 0 then
      local flying = dama and (p == 2 or p == -2)
      local ds = dirs[p]
      for i = 1, #ds do
        local step = STEP[ds[i]]
        local over = step[s]
        if flying then while over ~= 0 and b[over] == 0 do over = step[over] end end
        if over ~= 0 and b[over] * side < 0 then
          local to = step[over]
          if to ~= 0 and b[to] == 0 then return true end
        end
      end
    end
  end
  return false
end

-- every legal move of the side to move
function R.moves(pos)
  local b, side, variant = pos.b, pos.side, pos.variant
  local dirs = DIRS[variant]
  local dama = variant == R.DAMA
  local jumps = {}
  local caps, cv, path, taken = {}, {}, {}, {}
  for s = 1, 64 do
    local p = b[s]
    if p * side > 0 then
      local n0 = #jumps
      b[s] = 0                                          -- lifted: it may cross its own square
      if dama then dama_jumps(b, s, p, side, caps, cv, path, nil, jumps)
      else checkers_jumps(b, s, p, side, caps, cv, path, taken, jumps) end
      b[s] = p
      for i = n0 + 1, #jumps do
        local j = jumps[i]
        j.from, j.to, j.piece = s, j.path[#j.path], p
      end
    end
  end
  local list
  if #jumps > 0 then
    list = jumps
    if dama then
      -- the line taking the most must be played
      local most = 0
      for i = 1, #jumps do if #jumps[i].caps > most then most = #jumps[i].caps end end
      list = {}
      for i = 1, #jumps do if #jumps[i].caps == most then list[#list + 1] = jumps[i] end end
    end
  else
    list = {}
    for s = 1, 64 do
      local p = b[s]
      if p * side > 0 then
        local slide = dama and (p == 2 or p == -2)
        local ds = dirs[p]
        for i = 1, #ds do
          local step = STEP[ds[i]]
          local t = step[s]
          while t ~= 0 and b[t] == 0 do
            list[#list + 1] = { from = s, to = t, caps = NONE, cv = NONE, piece = p }
            if not slide then break end
            t = step[t]
          end
        end
      end
    end
  end
  local back = last_row(side)
  for i = 1, #list do
    local m = list[i]
    if (m.piece == 1 or m.piece == -1) and (m.to - 1) // 8 == back then m.promo = true end
  end
  return list
end

function R.make(pos, m)
  local b = pos.b
  b[m.from] = 0
  for _, s in ipairs(m.caps) do b[s] = 0 end
  b[m.to] = m.promo and 2 * pos.side or m.piece
  m.quiet = pos.quiet
  -- the draw count: moves of kings only, without a capture
  pos.quiet = (#m.caps > 0 or m.piece == 1 or m.piece == -1) and 0 or pos.quiet + 1
  pos.side = -pos.side
end

function R.unmake(pos, m)
  local b = pos.b
  pos.side = -pos.side
  b[m.to] = 0
  for i, s in ipairs(m.caps) do b[s] = m.cv[i] end
  b[m.from] = m.piece
  pos.quiet = m.quiet
end

-- "c3-d4", or "c3xe5xc7" for a capture
function R.text(m)
  if #m.caps == 0 then return R.name(m.from) .. '-' .. R.name(m.to) end   -- a plain move has no path
  local t = { R.name(m.from) }
  for _, s in ipairs(m.path) do t[#t + 1] = R.name(s) end
  return table.concat(t, 'x')
end

-- the legal move that R.text names, or nil
function R.find(pos, text)
  for _, m in ipairs(R.moves(pos)) do if R.text(m) == text then return m end end
  return nil
end

function R.count(pos)
  local n = { [1] = 0, [-1] = 0 }
  for s = 1, 64 do local p = pos.b[s]; if p > 0 then n[1] = n[1] + 1 elseif p < 0 then n[-1] = n[-1] + 1 end end
  return n
end

-- nil while the game goes on, else (result, why): 1 or -1 the side that won, 0 a draw. keys: the
-- R.key of every position so far, the current one last (the repetition rule).
R.QUIET_PLIES = 80
function R.outcome(pos, keys)
  if #R.moves(pos) == 0 then
    local n = R.count(pos)
    return -pos.side, n[pos.side] == 0 and 'no pieces left' or 'no move left'
  end
  if pos.quiet >= R.QUIET_PLIES then return 0, '40 moves without a capture' end
  if keys and #keys > 0 then
    local now, seen = keys[#keys], 0
    for i = 1, #keys do if keys[i] == now then seen = seen + 1 end end
    if seen >= 3 then return 0, 'threefold repetition' end
  end
  return nil
end

-- perft: the number of positions after `depth` moves (a move being a whole capture line)
function R.perft(pos, depth)
  if depth == 0 then return 1 end
  local total = 0
  for _, m in ipairs(R.moves(pos)) do
    R.make(pos, m)
    total = total + R.perft(pos, depth - 1)
    R.unmake(pos, m)
  end
  return total
end

return R
end

-- Checkers for XTOS Licorice, API 2.0 (uses tools/gamekit): English checkers or Turkish draughts
-- (Dama), against the reader at four levels or two players on one reader. Tap a piece (its moves
-- are marked), then where it goes; a capture goes the whole way in one tap, and when two lines end
-- on the same square the longer one is played. Undo takes back your last move (and the reply),
-- Hint frames a good move, New game picks the rules, the opponent and your side.
--
-- rules.lua holds both rule sets, engine.lua the reader's player; as in Chess it thinks in a
-- coroutine resumed from ctx:after timers in slices of about 200 ms, on a copy of the position.
-- The game is kept as its moves in game.txt and replayed on the next start.

local R = require('rules')
local E = require('engine')

local W, H = kit.W, kit.H
local SQ = 56
local BX, BY = (W - 8 * SQ) // 2, 150
local BTN_Y, BTN_H = 704, 60
local SLICE_MS = 200

local variant = R.CHECKERS
local pos = R.new(variant)
local history = {}              -- { m, text } per move played
local keys = {}                 -- R.key of every position so far (the repetition rule)
local mode, level, me = 'ai', 2, 1   -- 'ai' or 'two'; E.LEVELS index; your side (1 moves first)
local sel, targets = nil, {}    -- the square picked and its legal moves
local hint, last = nil, nil     -- the move framed, the last move played
local result = nil              -- { r, why } once the game is over
local think = nil               -- { co, kind = 'move' or 'hint' } while the reader thinks
local msg, ERR = nil, nil

local RULES = { [R.CHECKERS] = 'Checkers', [R.DAMA] = 'Dama' }

------------------------------------------------------------------ the game

-- in checkers the dark men move first ("Black"); in Dama White does
local function side_name(s)
  if variant == R.CHECKERS then return s > 0 and 'Black' or 'White' end
  return s > 0 and 'White' or 'Black'
end

local function save()
  local t = {}
  for i, h in ipairs(history) do t[i] = h.text end
  kit.write('game.txt', 'variant=' .. variant .. '\nmode=' .. mode .. '\nlevel=' .. level .. '\nme=' .. me ..
    '\nmoves=' .. table.concat(t, ' '))
end

local function check_end()
  local r, why = R.outcome(pos, keys)
  result = r and { r = r, why = why } or nil
  if not result then return end
  if r == 0 then msg = 'Draw: ' .. why .. '.'
  elseif mode == 'ai' then msg = (r == me and 'You win!' or 'The reader wins.') .. ' (' .. why .. ')'
  else msg = side_name(r) .. ' wins (' .. why .. ').' end
end

local function play(m)
  R.make(pos, m)
  history[#history + 1] = { m = m, text = R.text(m) }
  keys[#keys + 1] = R.key(pos)
  last = m
  sel, targets, hint, msg = nil, {}, nil, nil
  check_end()
  kit.moved()
end

local start_thinking

local function after_move()
  save()
  if mode == 'ai' and not result and pos.side ~= me then start_thinking('move') end
end

local function new_game(v, m, lv, side)
  think = nil
  variant, mode, level, me = v, m, lv or level, side or 1
  pos = R.new(variant)
  history, keys = {}, { R.key(pos) }
  sel, targets, hint, last, result = nil, {}, nil, nil, nil
  if mode == 'ai' then
    msg = RULES[variant] .. ': you play ' .. side_name(me) .. ' against the reader (' .. E.LEVELS[level].name .. ').'
  else
    msg = RULES[variant] .. ', two players: ' .. side_name(1) .. ' starts.'
  end
  after_move()
end

local function undo()
  think = nil
  if #history == 0 then return end
  repeat
    local h = table.remove(history)
    R.unmake(pos, h.m)
    table.remove(keys)
  until #history == 0 or mode ~= 'ai' or pos.side == me
  last = history[#history] and history[#history].m or nil
  sel, targets, hint, result = nil, {}, nil, nil
  msg = 'Move taken back.'
  check_end()
  save()
  if mode == 'ai' and pos.side ~= me then start_thinking('move') end
end

local function load()
  local t = kit.kv(kit.read('game.txt'))
  if not t.mode then new_game(R.CHECKERS, 'ai', 2, 1); return end
  think = nil
  variant = t.variant == R.DAMA and R.DAMA or R.CHECKERS
  mode = t.mode == 'two' and 'two' or 'ai'
  level = E.LEVELS[tonumber(t.level) or 0] and tonumber(t.level) or 2
  me = tonumber(t.me) == -1 and -1 or 1
  pos = R.new(variant)
  history, keys = {}, { R.key(pos) }
  for s in (t.moves or ''):gmatch('%S+') do
    local m = R.find(pos, s)
    if not m then break end
    play(m)
  end
  sel, targets, hint = nil, {}, nil
  check_end()
  if not result then msg = nil end
  if mode == 'ai' and not result and pos.side ~= me then start_thinking('move') end
end

------------------------------------------------------------------ the reader thinking

local function step(c)
  local th = think
  if not th then return end
  local ok, best = coroutine.resume(th.co)
  if think ~= th then return end                     -- Undo or New game while it thought
  if not ok then think = nil; ERR = tostring(best); kit.refresh(); return end
  if coroutine.status(th.co) ~= 'dead' then
    pcall(function() ctx:after(1, step) end)
    return
  end
  think = nil
  if not best then kit.refresh(); return end
  -- best is a move of the copy: the same one in the real position, found by its text
  local m = R.find(pos, R.text(best))
  if not m then kit.refresh(); return end
  if th.kind == 'move' then
    play(m)
    save()
  else
    hint = m
    msg = 'Hint: ' .. R.text(m) .. '.'
  end
  kit.refresh()
end

start_thinking = function(kind)
  local copy = R.copy(pos)
  local lv = kind == 'hint' and 3 or level
  local limit = kind == 'hint' and 2000 or nil
  local co = coroutine.create(function()
    return E.think(copy, lv, { clock = function() return kit.now_ms() or 0 end, slice_ms = SLICE_MS, limit_ms = limit })
  end)
  think = { co = co, kind = kind }
  pcall(function() ctx:after(30, step) end)
end

------------------------------------------------------------------ drawing

local function flip() return mode == 'ai' and me < 0 end

local function square_xy(s)
  local r, c = R.row(s), R.col(s)
  if flip() then r, c = 7 - r, 7 - c end
  return BX + c * SQ, BY + (7 - r) * SQ
end

-- a man: White an outlined disc, Black a solid one; a king has a crown ring inside
local function draw_piece(gg, p, x, y)
  local cx, cy = x + SQ // 2, y + SQ // 2
  local white = (variant == R.CHECKERS) == (p < 0)
  if white then
    gg:circle(cx, cy, 21, { fill = true, color = 0 })
    gg:circle(cx, cy, 21, { line_width = 3 })
    gg:circle(cx, cy, 15, { line_width = 1 })
    if p == 2 or p == -2 then gg:circle(cx, cy, 8, { fill = true }) end
  else
    gg:circle(cx, cy, 21, { fill = true })
    if p == 2 or p == -2 then
      gg:circle(cx, cy, 11, { fill = true, color = 0 })
      gg:circle(cx, cy, 6, { fill = true })
    else
      gg:circle(cx, cy, 15, { line_width = 2, color = 0 })
    end
  end
end

local function corners(gg, s)
  local x, y = square_xy(s)
  local L, E2 = 14, SQ - 4
  for _j, c in ipairs({ { 0, 0, 0, 0 }, { SQ - L, 0, E2, 0 }, { 0, E2, 0, SQ - L }, { SQ - L, E2, E2, SQ - L } }) do
    gg:rect(x + c[1], y + c[2], L, 4, { fill = true })
    gg:rect(x + c[3], y + c[4], 4, L, { fill = true })
  end
end

local function draw_board(gg)
  for s = 1, 64 do
    local x, y = square_xy(s)
    if variant == R.CHECKERS then
      if R.dark(s) then gg:rect(x + 3, y + 3, SQ - 6, SQ - 6, { line_width = 1 }) end
    else
      gg:rect(x, y, SQ, SQ, { line_width = 1 })                -- Dama uses every square
    end
  end
  gg:rect(BX - 2, BY - 2, 8 * SQ + 4, 8 * SQ + 4, { line_width = 2 })
  if last then
    corners(gg, last.from); corners(gg, last.to)
    -- where the pieces were taken: a small cross
    for _k, s in ipairs(last.caps) do
      local x, y = square_xy(s)
      gg:line(x + 20, y + 20, x + SQ - 20, y + SQ - 20); gg:line(x + SQ - 20, y + 20, x + 20, y + SQ - 20)
    end
  end
  for s = 1, 64 do
    local p = pos.b[s]
    if p ~= 0 then local x, y = square_xy(s); draw_piece(gg, p, x, y) end
  end
  local small = kit.font('small')
  for k = 1, 8 do
    local file = flip() and 9 - k or k
    local rank = flip() and k or 9 - k
    gg:text(BX + (k - 1) * SQ + SQ // 2 - 4, BY + 8 * SQ + 4, ('abcdefgh'):sub(file, file), { font = small })
    gg:text(2, BY + (k - 1) * SQ + SQ // 2 - 10, tostring(rank), { font = small })
  end
  if sel then
    local x, y = square_xy(sel)
    gg:rect(x + 1, y + 1, SQ - 2, SQ - 2, { line_width = 4 })
    local seen = {}
    for _k, m in ipairs(targets) do
      if not seen[m.to] then
        seen[m.to] = true
        local tx, ty = square_xy(m.to)
        if #m.caps > 0 then gg:circle(tx + SQ // 2, ty + SQ // 2, 10, { line_width = 3 })
        else gg:circle(tx + SQ // 2, ty + SQ // 2, 7, { fill = true }) end
      end
    end
  end
  if hint then
    for _k, s in ipairs({ hint.from, hint.to }) do
      local x, y = square_xy(s)
      gg:rect(x + 1, y + 1, SQ - 2, SQ - 2, { line_width = 2 }); gg:rect(x + 6, y + 6, SQ - 12, SQ - 12, { line_width = 2 })
    end
  end
end

local function recent()
  local out = {}
  for i = math.max(1, #history - 3), #history do
    out[#out + 1] = ((i + 1) // 2) .. (i % 2 == 1 and '. ' or '... ') .. history[i].text
  end
  return table.concat(out, '   ')
end

local BUTTONS = { 'Undo', 'Hint', 'New game' }
local function button_rect(k)
  local bw = math.floor((W - 24 - 2 * 8) / 3)
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

local function status()
  if result then return result.r == 0 and 'Draw' or 'Game over' end
  local must = R.has_capture(pos) and ' (a capture)' or ''
  if mode == 'ai' then
    if think and think.kind == 'move' then return 'The reader is thinking…' end
    if pos.side == me then return 'Your move' .. must end
  end
  return side_name(pos.side) .. ' to move' .. must
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    gg:text(12, 12, RULES[variant], { font = kit.font('large') })
    local n = R.count(pos)
    local who = mode == 'ai' and ('You: ' .. side_name(me) .. '   reader: ' .. E.LEVELS[level].name) or 'Two players'
    gg:text(12, 52, kit.short(who .. '   pieces ' .. n[1] .. '-' .. n[-1], 48), { font = kit.font('small') })
    gg:line(0, 90, W, 90)
    if kit.modal() then kit.draw_modal(gg); return end
    gg:text(12, 106, status(), { font = kit.font('medium') })
    draw_board(gg)
    local lines = {}
    if #history > 0 then lines[#lines + 1] = recent() end
    if msg then for _k, l in ipairs(kit.wrap(msg, 'small', W - 24)) do lines[#lines + 1] = l end end
    for k, l in ipairs(lines) do
      if k > 3 then break end
      gg:text(12, BY + 8 * SQ + 30 + (k - 1) * 22, kit.short(l, 52), { font = kit.font('small') })
    end
    for k, b in ipairs(BUTTONS) do
      local x, y, bw, bh = button_rect(k)
      kit.button(gg, x, y, bw, bh, b)
    end
    if ERR then gg:text(12, H - 30, kit.short('ERR ' .. ERR, 48), { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function square_at(x, y)
  if x < BX or x >= BX + 8 * SQ or y < BY or y >= BY + 8 * SQ then return nil end
  local c, r = (x - BX) // SQ, 7 - (y - BY) // SQ
  if flip() then r, c = 7 - r, 7 - c end
  return R.sq(r, c)
end

local function choose_side(v, lv)
  local first, second = (v == R.CHECKERS) and 'Black' or 'White', (v == R.CHECKERS) and 'White' or 'Black'
  kit.show({ title = 'Play as', lines = { RULES[v] .. ' against the reader, ' .. E.LEVELS[lv].name .. '. ' .. first .. ' moves first.' },
             rows = { { { first, function() kit.close(); new_game(v, 'ai', lv, 1) end },
                        { second, function() kit.close(); new_game(v, 'ai', lv, -1) end } },
                      { { 'Either', function() kit.close(); new_game(v, 'ai', lv, math.random(2) == 1 and 1 or -1) end } },
                      { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function choose_opponent(v)
  local function lv(i) return { E.LEVELS[i].name, function() kit.close(); choose_side(v, i) end } end
  kit.show({ title = RULES[v], lines = { 'Play against the reader, or two players on one reader.' },
             rows = { { lv(1), lv(2) }, { lv(3), lv(4) },
                      { { 'Two players', function() kit.close(); new_game(v, 'two', level, 1) end } },
                      { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function new_game_menu()
  kit.show({ title = 'New game', lines = { 'Checkers: diagonal moves on the dark squares. Dama (Turkish draughts): moves forward and sideways, the longest capture must be taken.' },
             rows = { { { 'Checkers', function() kit.close(); choose_opponent(R.CHECKERS) end },
                        { 'Dama', function() kit.close(); choose_opponent(R.DAMA) end } },
                      { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function my_turn()
  if result or think then return false end
  return mode == 'two' or pos.side == me
end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  for k = 1, 3 do
    local bx, by, bw, bh = button_rect(k)
    if x >= bx and x < bx + bw and y >= by and y < by + bh then
      if k == 1 then undo()
      elseif k == 2 then
        if my_turn() then msg = 'Looking for a good move…'; hint = nil; start_thinking('hint') end
      else new_game_menu() end
      return
    end
  end
  if not my_turn() then return end
  local s = square_at(x, y)
  if not s then sel, targets = nil, {}; return end
  local p = pos.b[s]
  if p ~= 0 and (p > 0) == (pos.side > 0) then
    if sel == s then sel, targets = nil, {}; return end
    local all = R.moves(pos)
    sel, targets = s, {}
    for _k, m in ipairs(all) do if m.from == s then targets[#targets + 1] = m end end
    if #targets == 0 then
      sel = nil
      msg = (#all > 0 and #all[1].caps > 0) and 'A capture must be made: pick a piece that can take.' or 'That piece cannot move.'
    else msg = nil end
  elseif sel then
    -- the move ending on that square; of several, the one taking the most
    local best
    for _k, m in ipairs(targets) do
      if m.to == s and (not best or #m.caps > #best.caps) then best = m end
    end
    if not best then sel, targets = nil, {}; return end
    play(best)
    after_move()
  end
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if kit.modal() and ev.key == 'back' and kit.modal().cancel then kit.modal().cancel() end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  local ok, e = pcall(load)
  if not ok then ERR = tostring(e) end
end
function on_leave() think = nil; pcall(save) end

if rawget(_G, '__TEST') then
  __TEST.api = { pos = function() return pos end, R = R, E = E, square_xy = square_xy, history = function() return history end,
                 result = function() return result end, thinking = function() return think end,
                 mode = function() return mode end, me = function() return me end, level = function() return level end,
                 variant = function() return variant end, sel = function() return sel end, hint = function() return hint end,
                 set_position = function(v, key)
                   think = nil
                   variant = v
                   pos = R.from_key(v, key); history, keys = {}, { R.key(pos) }
                   sel, targets, hint, last, result, msg = nil, {}, nil, nil, nil, nil
                 end }
end
